  add('solid','advanced','立方体の頂点Ａから、辺にそって進んで、いちばん遠い頂点Ｇまで行きます。辺を何本通れば最短ですか。',3,[2,4,6],['Ａから見て、たて・横・高さ、それぞれ１回ずつ進みます。','ななめには進めません。'],'いちばん遠い頂点へは、横・たて・高さの順に１本ずつ、全部で３本通れば行けます。',null);
  add('solid','advanced','たて６cm、横４cm、高さ４cmの箱に、１辺２cmの立方体の積み木をすきまなくつめます。積み木は何こ入りますか。',12,[24,48,96],['たて・横・高さに、それぞれ何こならぶか考えます。','６ ÷ ２、４ ÷ ２、４ ÷ ２です。'],'たてに３こ、横に２こ、高さに２だんなので、3 × 2 × 2＝12こです。',null);
  add('solid','advanced','雪原基地の倉庫に、木箱をたてに３こ、横に４こならべ、それを２だんに積みます。木箱は全部で何こですか。',24,[12,14,18],['１だんに何こならぶか先に求めます。','それにだんの数をかけます。'],'１だんは 3 × 4＝12こ。２だんなので、12 × 2＝24こです。',null);
  add('solid','advanced','直方体の頂点Ａを（０、０、０）として、右へ３、奥へ２、高さ４の頂点を（３、２、４）と表します。この頂点と同じ高さにある頂点は、全部で何こですか。（その頂点も数えます）',4,[1,2,8],['高さが同じ頂点は、同じ面の上にあります。','上の面（高さ４）の頂点を数えます。'],'高さ４の面（上の面）には、頂点が４つあります。その頂点と同じ高さの頂点は、４こです。',null);
  add('solid','advanced','たて５cm、横３cm、高さ２cmの直方体で、いちばん面積が大きい面の面積は何cm²ですか。',15,[6,10,30],['面の種類は３つあります。','いちばん長い辺どうしの面を選びましょう。'],'面積は、5 × 3＝15、5 × 2＝10、3 × 2＝６。いちばん大きいのは15cm²です。',null);
  // 垂直・平行と四角形（30問）
  add('quad','basic','平行四辺形で、向かい合う辺が平行になっている組は、何組ありますか。',2,[1,3,4],['向かい合う辺は、上と下、左と右の組があります。','どちらの組も平行です。'],'平行四辺形は、向かい合う２組の辺がどちらも平行です。',null);
  add('quad','basic','長方形の４つの角は、それぞれ何度ですか。',90,[60,180,360],['長方形の角はすべて同じ大きさです。','直角は何度でしょう。'],'長方形の角は４つとも直角で、90度です。',null);
  add('quad','basic','正方形の特ちょうとして、正しいものはどれですか。','４つの角が直角で、４つの辺の長さが等しい',['４つの角が直角だが、辺の長さはちがうこともある','辺の長さは等しいが、角は直角でないこともある','向かい合う辺が平行ではない'],['正方形は、長方形でもあり、ひし形でもあります。','角と辺の両方を考えましょう。'],'正方形は、４つの角が直角（長方形の特ちょう）で、４つの辺の長さが等しい（ひし形の特ちょう）四角形です。',null);
  add('quad','basic','平行四辺形ＡＢＣＤで、角Ａが70度のとき、向かい合う角Ｃは何度ですか。',70,[110,20,290],['平行四辺形の向かい合う角は、大きさが等しくなります。','角Ａの向かい側の角を考えます。'],'平行四辺形の向かい合う角は等しいので、角Ｃも70度です。',null);
  add('quad','basic','台形で、向かい合う辺が平行になっている組は、何組ですか。',1,[0,2,4],['台形は、向かい合う１組の辺だけが平行な四角形です。','平行四辺形とのちがいを考えましょう。'],'台形は、向かい合う１組の辺だけが平行です。',null);
  add('quad','basic','四角形の対角線は、何本引けますか。',2,[1,3,4],['向かい合う頂点を結ぶ線が対角線です。','頂点が４つあるので、向かい合う組を数えます。'],'向かい合う頂点の組が２組あるので、対角線は２本です。',null);
  add('quad','basic','１辺が５cmのひし形があります。まわりの長さは何cmですか。',20,[10,15,25],['ひし形は、４つの辺の長さがすべて等しい四角形です。','１辺の長さに辺の数をかけます。'],'5 × 4＝20。まわりの長さは20cmです。',null);

  add('quad','standard','平行四辺形ＡＢＣＤで、角Ａが70度のとき、となり合う角Ｂは何度ですか。',110,[70,20,290],['平行四辺形のとなり合う角を足すと、180度になります。','180度から70度を引きます。'],'180－70＝110。角Ｂは110度です。',null);
  add('quad','standard','平行四辺形ＡＢＣＤで、辺ＡＢが８cm、辺ＢＣが５cmです。まわりの長さは何cmですか。',26,[13,40,21],['向かい合う辺の長さは等しいです。','８cmの辺と５cmの辺が、それぞれ２本ずつあります。'],'（8＋5）× 2＝26。まわりの長さは26cmです。',null);
  add('quad','standard','ひし形の２本の対角線は、どのように交わりますか。','垂直に交わる',['平行になる','交わらない','長さが必ず等しくなる'],['ひし形の対角線を引いた図を思いうかべましょう。','交わってできる角は直角です。'],'ひし形の２本の対角線は、おたがいの真ん中で垂直に交わります。',null);
  add('quad','standard','平行四辺形ＡＢＣＤの対角線ＡＣとＢＤが点Ｏで交わっています。ＡＣが10cmのとき、ＡＯは何cmですか。',5,[10,20,2],['平行四辺形の対角線は、おたがいの真ん中で交わります。','ＡＣを２等分した長さがＡＯです。'],'点Ｏは対角線の真ん中なので、ＡＯ＝10 ÷ 2＝５cmです。',null);
  add('quad','standard','四角形の４つの角の大きさを合わせると、何度になりますか。',360,[180,270,720],['四角形は、対角線で２つの三角形に分けられます。','三角形の角の和は180度です。'],'三角形２つ分なので、180 × 2＝360。４つの角の和は360度です。',null);
  add('quad','standard','四角形の３つの角が、90度、80度、100度です。残りの角は何度ですか。',90,[80,100,270],['四角形の角の和は360度です。','わかっている３つの角を足して、360度から引きます。'],'90＋80＋100＝270。360－270＝90。残りの角は90度です。',null);
  add('quad','standard','台形で、平行になっている２つの辺を、それぞれ何といいますか。','上底と下底',['高さと底辺','対角線と対辺','直線と曲線'],['平行な辺の上の方と下の方に名前があります。','「底」という字のつく名前です。'],'台形の平行な２つの辺は、上の辺を上底、下の辺を下底といいます。',null);
  add('quad','standard','直線ａと直線ｂが垂直で、直線ｃも直線ｂに垂直です。直線ａと直線ｃは、どんな関係ですか。','平行',['垂直','交わって、直角にならない','同じ直線になる'],['直線ｂに垂直な直線は、すべて同じ向きになります。','同じ直線に垂直な２本の直線は、どこまでも交わりません。'],'同じ直線に垂直な２本の直線は、平行になります。',null);
  add('quad','standard','直線ａと直線ｂは平行で、直線ｃが直線ａに垂直です。直線ｃと直線ｂは、どんな関係ですか。','垂直',['平行','ななめに交わる','関係はない'],['平行な直線は、同じ向きにのびています。','直線ａと同じ角度で直線ｃに交わります。'],'平行な直線の一方に垂直な直線は、もう一方にも垂直です。',null);
  add('quad','standard','まわりの長さが36cmのひし形があります。１辺は何cmですか。',9,[6,12,18],['ひし形は、４つの辺の長さがすべて等しいです。','まわりの長さを辺の数でわります。'],'36 ÷ 4＝９。１辺は９cmです。',null);
  add('quad','standard','平行な２本の直線の間のはばは、どこではかっても、どうなりますか。','いつも同じ',['右に行くほど広くなる','右に行くほどせまくなる','はかる場所によって変わる'],['平行な直線は、交わらず、はなれ方も変わりません。','直線に垂直にはかります。'],'平行な直線は、どこではかっても、間のはばがいつも同じです。',null);
  add('quad','standard','正方形の２本の対角線には、どんな特ちょうがありますか。','長さが等しく、垂直に交わる',['長さが等しいが、垂直には交わらない','垂直に交わるが、長さは等しくない','長さも等しくなく、垂直にも交わらない'],['正方形は、長方形でもあり、ひし形でもあります。','長方形の対角線とひし形の対角線の特ちょうを合わせます。'],'正方形の対角線は、長方形のように長さが等しく、ひし形のように垂直に交わります。',null);

  add('quad','advanced','平行四辺形ＡＢＣＤで、角Ａが角Ｂの２倍の大きさです。角Ａは何度ですか。',120,[60,90,100],['角Ａと角Ｂは、となり合う角です。足すと180度になります。','角Ｂを□度として、角Ａ＝□×２で考えます。'],'角Ａ＋角Ｂ＝180度で、角Ａは角Ｂの２倍です。角Ｂ＝180 ÷ 3＝60度、角Ａ＝60 × 2＝120度です。',null);
  add('quad','advanced','四角形の４つの角のうち、２つが85度と95度で、残りの２つの角は同じ大きさです。残りの角は、それぞれ何度ですか。',90,[85,95,180],['四角形の角の和は360度です。','85＋95を先に計算し、残りを２でわります。'],'85＋95＝180。360－180＝180。２つの角が同じなので、180 ÷ 2＝90。それぞれ90度です。',null);
  add('quad','advanced','まわりの長さが36cmの平行四辺形があります。辺ＡＢが７cmのとき、辺ＢＣは何cmですか。',11,[18,22,29],['向かい合う辺の長さは等しいです。','まわりの長さの半分が、ＡＢ＋ＢＣです。'],'36 ÷ 2＝18。18－7＝11。辺ＢＣは11cmです。',null);
  add('quad','advanced','長方形ＡＢＣＤの対角線ＡＣとＢＤが点Ｏで交わります。ＡＣが14cmのとき、ＯＢは何cmですか。',7,[14,28,10],['長方形の２本の対角線は、長さが等しく、おたがいの真ん中で交わります。','ＢＤの長さをまず考えましょう。'],'ＢＤ＝ＡＣ＝14cmで、点ＯはＢＤの真ん中なので、ＯＢ＝14 ÷ 2＝７cmです。',null);
  add('quad','advanced','２本の対角線が、長さが等しく、垂直に交わり、おたがいの真ん中で交わる四角形は、どれですか。','正方形',['長方形','ひし形','平行四辺形'],['長さが等しい対角線をもつのは、どの四角形でしょう。','垂直に交わる対角線をもつのは、どの四角形でしょう。'],'対角線の長さが等しいのは長方形、垂直に交わるのはひし形です。その両方をもつのは正方形です。',null);
  add('quad','advanced','次の四角形のうち、２本の対角線がいつも垂直に交わるものは、どれですか。','ひし形',['長方形','平行四辺形','台形'],['対角線を引いた図を、それぞれ思いうかべます。','４つの辺の長さが等しい四角形です。'],'ひし形の対角線は、いつも垂直に交わります。長方形や平行四辺形は、垂直に交わらないこともあります。',null);
  add('quad','advanced','向かい合う辺が２組とも平行で、４つの角がすべて等しい四角形は、どれですか。','長方形',['ひし形','台形','平行四辺形'],['４つの角がすべて等しいと、それぞれ何度でしょう。','角が全部直角で、向かい合う辺が平行な四角形です。'],'４つの角の和は360度なので、すべて等しければ90度ずつです。向かい合う辺が平行で４つの角が直角なのは、長方形です。',null);
  add('quad','advanced','４つの角がすべて直角である四角形を、すべて選んだものはどれですか。','正方形と長方形',['正方形とひし形','ひし形と平行四辺形','長方形とひし形'],['ひし形は、角が直角でないこともあります。','平行四辺形も、角が直角でないこともあります。'],'正方形と長方形は、４つの角がすべて直角です。ひし形や平行四辺形は、直角にならないこともあります。',null);
  add('quad','advanced','雪原基地の看板は、辺ＡＢが９cm、辺ＢＣが６cmの平行四辺形です。ふちに紙テープを２周まくと、テープは何cm必要ですか。（つなぎ目は考えません）',60,[30,15,54],['１周分のまわりの長さを先に求めます。','それを２倍します。'],'１周は（9＋6）× 2＝30cm。２周分は 30 × 2＝60cmです。',null);
  add('quad','advanced','ひし形ＡＢＣＤで、角Ａが50度のとき、となり合う角Ｂは何度ですか。',130,[50,40,310],['ひし形は、平行四辺形の仲間です。','となり合う角を足すと180度になります。'],'180－50＝130。角Ｂは130度です。',null);
  add('quad','advanced','正方形ＡＢＣＤで、辺ＡＢに平行な辺は何本、垂直な辺は何本ありますか。','平行１本、垂直２本',['平行２本、垂直１本','平行１本、垂直１本','平行２本、垂直２本'],['正方形の辺を１つずつ、辺ＡＢと比べましょう。','向かい合う辺は平行、となり合う辺は垂直です。'],'辺ＡＢに平行なのは向かい合う辺ＤＣの１本、垂直なのはとなり合う辺ＡＤとＢＣの２本です。',null);
  // 折れ線グラフ（30問）
  add('graph','basic','図は、雪原基地の積雪の深さです。２月の積雪は何cmですか。',55,[40,35,12],['２月の点を探します。','その点の高さを、左の目もりで読みます。'],'２月の点は55の高さにあるので、55cmです。',SNOW);
  add('graph','basic','図の積雪の深さが、いちばん深いのは何月ですか。','２月',['１月','３月','４月'],['グラフのいちばん高い点を探します。','その下の月を読みます。'],'いちばん高い点は55cmの２月です。',SNOW);
  add('graph','basic','折れ線グラフは、どんなことを表すのにむいていますか。','時間とともに変わっていくようす',['ものの数の多さをくらべること','全体のうちわけを見ること','ものの形を調べること'],['気温や水の量などを、時間を追って表したグラフです。','線のかたむきで、変わり方がわかります。'],'折れ線グラフは、時間とともに量が変わっていくようすを表すのにむいています。',null);
  add('graph','basic','折れ線グラフで、線が右上がりになっているところは、どんなようすですか。','だんだん増えている',['だんだんへっている','変わっていない','最初の量と同じ'],['右にいくほど、点が高くなっています。','点が高いほど、量は大きいです。'],'右上がりの線は、量が増えていることを表します。',null);
  add('graph','basic','図は、１週間に使ったまきの数です。火曜日は何本ですか。',26,[20,24,18],['火曜日の点を探します。','左の目もりで高さを読みます。'],'火曜日の点は26の高さなので、26本です。',WOOD);
  add('graph','basic','折れ線グラフで、線が横にまっすぐになっているところは、どんなようすですか。','変わっていない',['増えている','へっている','わからない'],['左と右で、点の高さを比べます。','高さが同じなら、量は同じです。'],'横にまっすぐな線は、量が変わっていないことを表します。',null);
  add('graph','basic','図は、水そうに入っている水の量です。10分のとき、水は何Lですか。',50,[30,70,10],['10分の点を探します。','その点の高さを読みます。'],'10分の点は50の高さなので、50Lです。',WATER);

  add('graph','standard','図の積雪の深さは、３月から４月までに何cmへりましたか。',23,[12,35,47],['３月と４月の深さを読みます。','前の月から、あとの月を引きます。'],'３月は35cm、４月は12cmです。35－12＝23。23cmへりました。',SNOW);
  add('graph','standard','図で、水の量が70Lになるのは何分のときですか。','15分',['10分','５分','20分'],['左の目もりの70から横に見ていきます。','点の真下の時間を読みます。'],'70Lの点の真下は15分です。',WATER);
  add('graph','standard','図は、１週間のまきの数です。前の日より増えた日は、何日ありますか。',2,[1,3,4],['となり合う日と点の高さを比べます。','右上がりになっているところを数えます。'],'月→火は増え、火→水・水→木はへり、木→金は同じ、金→土は増えます。増えた日は火曜日と土曜日の２日です。',WOOD);
  add('graph','standard','図で、まきの数が前の日と変わらなかったのは、何曜日から何曜日の間ですか。','木曜日から金曜日',['月曜日から火曜日','火曜日から水曜日','金曜日から土曜日'],['横にまっすぐな線を探します。','高さが同じ２つの点を見つけます。'],'木曜日と金曜日はどちらも18本なので、木曜日から金曜日の間です。',WOOD);
  add('graph','standard','図は、町の人口です。2019年から2022年までに、人口は何人増えましたか。',40,[60,20,180],['2019年と2022年の人口を読みます。','あとの人口から、はじめの人口を引きます。'],'2019年は140人、2022年は180人です。180－140＝40。40人増えました。',POP);
  add('graph','standard','図で、町の人口が変わらなかったのは、何年から何年の間ですか。','2020年から2021年',['2018年から2019年','2019年から2020年','2021年から2022年'],['横にまっすぐな線を探します。','高さが同じ２つの点を見つけます。'],'2020年と2021年はどちらも150人なので、2020年から2021年の間です。',POP);
  add('graph','standard','図の気温が、いちばん高いのは何時ですか。','12時',['９時','15時','18時'],['グラフのいちばん高い点を探します。','その下の時刻を読みます。'],'いちばん高い点は10℃の12時です。',TEMP);
  add('graph','standard','図で、気温の上がり方がいちばん大きいのは、いつからいつの間ですか。','９時から12時',['６時から９時','12時から15時','15時から18時'],['右上がりの区間だけを比べます。','上がった量を、それぞれ求めましょう。'],'６時→９時は３℃、９時→12時は４℃上がります。12時のあとは下がります。いちばん大きいのは、９時から12時です。',TEMP);
  add('graph','standard','図で、水の量は、５分ごとに何Lずつ増えていますか。',20,[10,30,40],['となり合う点の差を調べます。','０分と５分の水の量を読みます。'],'０分は10L、５分は30Lなので、30－10＝20。５分ごとに20Lずつ増えています。',WATER);
  add('graph','standard','折れ線グラフのたてのじくで、１目もりが２Lのとき、点が６目もりの高さにあります。水は何Lですか。',12,[6,8,3],['１目もりの大きさに、目もりの数をかけます。','２Lが６つ分です。'],'2 × 6＝12。水は12Lです。',null);
  add('graph','standard','「いつ、どれだけ変わったか」を調べるのに、いちばんむいているグラフはどれですか。','折れ線グラフ',['棒グラフ','絵グラフ','表だけ'],['時間とともに変わっていくようすを表すグラフです。','点を線でつないで表します。'],'時間による変わり方を調べるには、折れ線グラフがむいています。',null);
  add('graph','standard','図の積雪の深さで、２月と４月のちがいは何cmですか。',43,[3,12,55],['２月と４月の深さを読みます。','大きい方から小さい方を引きます。'],'２月は55cm、４月は12cmです。55－12＝43。43cmのちがいです。',SNOW);

