  add('table','standard','読書調べの表で、２つの組の人数は、全部で何人ですか。',42,[25,17,40],['１組の合計と２組の合計を足します。','「読んだ人」と「読まなかった人」の合計を足してもよいです。'],'22＋20＝42。全部で42人です。',T2);
  add('table','standard','サッカーに入っている人が10人、バスケットボールに入っている人が７人で、そのうち、両方に入っている人が３人です。どちらかに入っている人は、全部で何人ですか。',14,[17,13,20],['10＋７とすると、両方に入っている人を２回数えてしまいます。','両方に入っている人の分を引きます。'],'10＋7－3＝14。どちらかに入っている人は14人です。',null);
  add('table','standard','サッカーに入っている人が10人、バスケットボールに入っている人が７人で、両方に入っている人は３人です。クラス全体が19人のとき、どちらにも入っていない人は何人ですか。',5,[2,9,12],['どちらかに入っている人を先に求めます。','全体の人数から、その人数を引きます。'],'どちらかに入っているのは10＋7－3＝14人です。19－14＝５。どちらにも入っていない人は５人です。',null);
  add('table','standard','男の子が12人、女の子が９人います。表の「合計」のらんに21人と書くのは、どの場合ですか。','男の子と女の子の人数を合わせたとき',['男の子の人数だけのとき','女の子の人数だけのとき','男の子の人数から女の子の人数を引いたとき'],['合計は、いくつかの数を合わせた数です。','12と９を使って計算してみましょう。'],'12＋9＝21なので、男の子と女の子を合わせた人数が、合計の21人です。',null);

  add('table','advanced','４年１組の40人のうち、犬をかっている人が18人、ねこをかっている人が15人、両方をかっている人が６人です。どちらもかっていない人は何人ですか。',13,[7,10,19],['犬かねこのどちらかをかっている人を先に求めます。','両方かっている６人は、２回数えています。'],'18＋15－6＝27人がどちらかをかっています。40－27＝13。どちらもかっていない人は13人です。',null);
