  add('abacus','basic','そろばんの、上の玉１つは、いくつを表しますか。',5,[1,10,50],['上の玉と下の玉では、表す大きさがちがいます。','下の玉は１つで１を表します。'],'上の玉は１つで５、下の玉は１つで１を表します。',null);
  add('abacus','basic','図のそろばんが表している数はいくつですか。',35,[53,38,305],['はりに近づけた玉を数えます。','左のけたが十の位です。'],'十の位が３、一の位が５なので35です。',abacus([3,5],['十','一']));
  add('abacus','basic','図のそろばんが表している数はいくつですか。',602,[62,620,206],['０のけたには、玉を１つも近づけません。','百・十・一の位を順に読みます。'],'百の位が６、十の位が０、一の位が２なので602です。',abacus([6,0,2],['百','十','一']));
  add('abacus','basic','そろばんで７を表すとき、玉はどのように使いますか。','上の玉１つと、下の玉２つ',['上の玉２つと、下の玉１つ','上の玉１つと、下の玉７つ','下の玉７つ'],['上の玉は５を表します。','７は、５と何を合わせた数でしょう。'],'７＝５＋２なので、上の玉１つ（５）と、下の玉２つ（２）を使います。',null);

