  add('abacus','standard','そろばんで4003を表すとき、玉を１つも入れないけたは、いくつありますか。',2,[1,3,4],['4003は４けたの数です。','百の位と十の位は、どんな数字でしょう。'],'4003は、百の位と十の位が０です。玉を入れないけたは２つです。',null);
  add('abacus','standard','そろばんの１つのけたで表せる数は、０からいくつまでですか。',9,[5,10,4],['上の玉は５、下の玉は４つで４までです。','上の玉と下の玉をぜんぶ使うと、最大になります。'],'上の玉１つ（５）と下の玉４つ（４）を合わせると９です。10になると、左のけたにくり上がります。',null);
  add('abacus','standard','図のそろばんの小数に0.5を足します。答えはいくつですか。',2.3,[1.3,2.8,2.5],['図は1.8を表しています。','十分の一の位で８＋５を計算します。'],'1.8＋0.5＝2.3です。十分の一の位が13になるので、一の位にくり上がります。',abacus([1,8],['一','十分の一']));
  add('abacus','standard','図のそろばんの数を10倍すると、いくつになりますか。',320,[32,3200,302],['図は32を表しています。','10倍すると、すべてのけたが１つ左にずれます。'],'32の10倍は320です。',abacus([3,2],['十','一']));

  add('abacus','advanced','図のそろばんの数から1200を引くと、いくつになりますか。',3300,[4200,3500,3200],['図は4500を表しています。','百の位から引きます。'],'4500－1200＝3300です。',abacus([4,5,0,0],['千','百','十','一']));
  add('abacus','advanced','図のそろばんの小数に0.07を足します。答えはいくつですか。',1.02,[0.102,1.12,0.97],['図は0.95を表しています。','百分の一の位で５＋７を計算します。'],'0.95＋0.07＝1.02です。百分の一の位が12になってくり上がり、十分の一の位が10になってさらにくり上がります。',abacus([0,9,5],['一','十分の一','百分の一']));
  add('abacus','advanced','図のそろばんは、持っているお金を表しています。1000円出して買いものをするとき、おつりはいくらですか。（図は買いものの代金です）',363,[463,373,637],['図は637円を表しています。','1000－637を計算します。'],'1000－637＝363。おつりは363円です。',abacus([6,3,7],['百','十','一']));
  add('abacus','advanced','そろばんで98に７を足します。答えはいくつですか。',105,[915,95,106],['一の位で８＋７＝15となります。','くり上がりに気をつけます。'],'98＋7＝105。一の位が15でくり上がり、十の位が10になってさらにくり上がります。',null);
  add('abacus','advanced','図のそろばんの小数から0.15を引きます。答えはいくつですか。',2.87,[3.17,2.97,2.13],['図は3.02を表しています。','百分の一の位から引けないので、くり下げます。'],'3.02－0.15＝2.87です。',abacus([3,0,2],['一','十分の一','百分の一']));
  add('abacus','advanced','雪原基地で、まきを１日目に128本、２日目に245本、３日目に367本集めました。そろばんで全部を足すと、何本ですか。',740,[630,730,750],['百の位、十の位、一の位の順に足していきます。','くり上がりに気をつけます。'],'128＋245＝373、373＋367＝740。全部で740本です。',null);
