  add('decimal_calc','basic','１こ0.8kgの木箱が６こあります。全部で何kgですか。','4.8',['48','0.48','6.8'],['8×6を計算します。','0.8は0.1が８こ分です。'],'0.8×6＝4.8。全部で4.8kgです。',null);
  add('decimal_calc','basic','9.6mの布を、４まいに同じ長さで切ります。１まいは何mですか。','2.4',['24','0.24','5.6'],['96÷4を使って考えます。','小数点を、わられる数の位置にそろえます。'],'9.6÷4＝2.4。１まいは2.4mです。',null);

  add('decimal_calc','standard','１こ1.25kgの荷物が６こあります。全部で何kgですか。','7.5',['75','0.75','7.25'],['125×6を計算します。','小数点を２けたもどします。'],'125×6＝750なので、1.25×6＝7.50＝7.5。全部で7.5kgです。',null);
  add('decimal_calc','standard','8.4Lの水を、６つのバケツに同じ量ずつ入れます。１つのバケツに何L入りますか。','1.4',['14','0.14','2.4'],['84÷6を使って考えます。','商の小数点は、わられる数の小数点の真上です。'],'8.4÷6＝1.4。１つのバケツに1.4L入ります。',null);
