  add('fraction','basic','1/5を３こ集めた数を、分数で表しましょう。','3/5',['1/15','5/3','3/15'],['1/5が何こ分かを、分子で表します。','分母は、全体を何等分したかを表します。'],'1/5が３こ分なので、3/5です。',null);
  add('fraction','basic','3/3は、いくつと同じ大きさですか。','１',['0','3','1/3'],['分母と分子が同じ数です。','全体を３等分した、３つ分は全部です。'],'3/3は全体と同じなので、１です。',null);
  add('fraction','basic','次の分数のうち、仮分数はどれですか。','7/4',['3/4','2/5','１と1/4'],['仮分数は、分子が分母と同じか、分母より大きい分数です。','分子と分母を比べます。'],'7/4は分子が分母より大きいので、仮分数です。3/4と2/5は真分数、１と1/4は帯分数です。',null);
