  add('fraction','basic','帯分数「１と1/4」を、仮分数にしましょう。','5/4',['2/4','4/4','1/5'],['１は4/4です。','4/4に1/4を足します。'],'１と1/4＝4/4＋1/4＝5/4です。',null);
