  add('fraction','standard','11/3を、帯分数にしましょう。','３と2/3',['３と1/3','２と5/3','４と2/3'],['３つで１になるので、3/3が何こ取り出せるか考えます。','11÷3の商とあまりを使います。'],'11÷3＝３あまり２。11/3＝３と2/3です。',null);
  add('fraction','standard','3/5と4/5では、どちらが大きいですか。','4/5',['3/5','同じ大きさ','くらべられない'],['分母が同じなので、分子で比べます。','1/5が何こ分かを比べましょう。'],'分母が同じときは、分子が大きいほうが大きい分数です。4/5が大きいです。',null);
  add('fraction','standard','7/5と、帯分数の「１と2/5」では、大きさはどうなっていますか。','同じ大きさ',['7/5のほうが大きい','１と2/5のほうが大きい','くらべられない'],['１と2/5を仮分数に直してみます。','１は5/5です。'],'１と2/5＝5/5＋2/5＝7/5なので、同じ大きさです。',null);
