  add('fraction','advanced','５−2/7を計算しましょう。','４と5/7',['４と2/7','３と5/7','５と2/7'],['５を、整数と分数に分けて考えます。','５＝４と7/7です。'],'５＝４と7/7。４と7/7−2/7＝４と5/7です。',null);
