  add('fraction','advanced','□−2/9＝5/9です。□にあてはまる分数は何ですか。','7/9',['3/9','5/9','10/9'],['引き算の□は、足し算で求めます。','5/9＋2/9を計算します。'],'□＝5/9＋2/9＝7/9です。',null);
  add('fraction','advanced','4/3、１と2/3、２を、小さい順にならべたものはどれですか。','4/3、１と2/3、２',['２、１と2/3、4/3','１と2/3、4/3、２','4/3、２、１と2/3'],['どれも、仮分数か帯分数のどちらかにそろえます。','たとえば、すべて分母が３の仮分数にします。'],'１と2/3＝5/3、２＝6/3です。4/3、5/3、6/3の順なので、4/3、１と2/3、２です。',null);
