  add('fraction','advanced','分母が５の分数で、3/5より大きく、１より小さい分数は何ですか。','4/5',['2/5','5/5','6/5'],['分子が、３より大きく５より小さい数を考えます。','１より小さいのは、真分数です。'],'分子が４のとき、4/5は3/5より大きく、１より小さいです。',null);
  add('fraction','advanced','1/6を15こ集めた数を、帯分数で表しましょう。','２と3/6',['２と1/6','１と3/6','３と2/6'],['まず15/6の仮分数にします。','15÷6の商とあまりを使います。'],'15/6。15÷6＝２あまり３なので、２と3/6です。',null);
  add('fraction','advanced','分母が８の真分数1/8、2/8、…、7/8を、全部足すと、いくつになりますか。帯分数で答えましょう。','３と4/8',['３と7/8','４と1/8','２と6/8'],['分子を、１から７まで足します。','合計の分子を、分母の８で整数と分数に分けます。'],'１＋２＋…＋７＝28。28/8＝３と4/8です。',null);
