  add('area','standard','たて10cm、横８cmの長方形から、たて４cm、横３cmの長方形を切り取りました。のこりの面積は何cm²ですか。',68,[80,12,92],['大きい長方形の面積から、切り取った面積を引きます。','それぞれの面積を求めましょう。'],'10 × 8＝80、4 × 3＝12。80－12＝68。のこりの面積は68cm²です。',null);
  add('area','standard','１km²は何m²ですか。','1000000',['1000','10000','100000'],['１kmは1000mです。','1000m × 1000mを計算します。'],'1000 × 1000＝1000000。１km²＝1000000m²です。',null);
  add('area','standard','たて８m、横７mの教室のゆかに、１辺１mの正方形のマットをすきまなくしきます。マットは何まい使いますか。',56,[15,30,64],['ゆかの面積が、何m²か考えます。','１まいが１m²なので、面積と同じ数になります。'],'8 × 7＝56m²。マット１まいが１m²なので、56まい使います。',null);
  add('area','standard','Ａの長方形は、たて６cm、横５cmです。Ｂの長方形は、たて９cm、横４cmです。どちらが何cm²広いですか。','Ｂが６cm²広い',['Ａが６cm²広い','Ｂが２cm²広い','Ａが２cm²広い'],['それぞれの面積を求めます。','面積を比べて、差を求めます。'],'Ａは5×6＝30cm²、Ｂは9×4＝36cm²です。36－30＝6。Ｂが６cm²広いです。',null);
  add('area','standard','たて４cm、横６cmの長方形と、たて４cm、横３cmの長方形を、ならべてくっつけました。全部の面積は何cm²ですか。',36,[24,12,48],['それぞれの面積を求めて足します。','たての長さがそろっているので、横をつなげて考えてもよいです。'],'4 × 6＝24、4 × 3＝12。24＋12＝36。全部で36cm²です。',null);

  add('area','advanced','まわりの長さが20cmの長方形があります。たてと横の長さが整数のとき、面積がいちばん大きくなるのは何cm²のときですか。',25,[24,21,16],['たて＋横は、20 ÷ 2＝10です。','たてと横の組み合わせを、いろいろ考えて面積を比べます。'],'たて＋横＝10です。（１、９）は９、（２、８）は16、（３、７）は21、（４、６）は24、（５、５）は25なので、いちばん大きいのは25cm²です。',null);
  add('area','advanced','面積が36cm²で、たてが４cmの長方形があります。この長方形のまわりの長さは何cmですか。',26,[13,40,36],['横の長さを先に求めます。','まわりの長さは、（たて＋横）×２です。'],'横は36÷4＝9cmです。まわりの長さは（4＋9）×2＝26cmです。',null);
  add('area','advanced','たて３m、横５mのかべにペンキをぬります。ペンキ１Lで３m²ぬれます。ペンキは何L必要ですか。',5,[3,8,15],['かべの面積を先に求めます。','面積を、１Lでぬれる面積でわります。'],'3 × 5＝15m²。15 ÷ 3＝5。ペンキは５L必要です。',null);
  add('area','advanced','たて12m、横15mの長方形の土地の中に、たて４m、横６mの長方形の池があります。池をのぞいた土地の面積は何m²ですか。',156,[180,24,204],['土地全体の面積から、池の面積を引きます。','それぞれの面積を求めましょう。'],'12 × 15＝180、4 × 6＝24。180－24＝156。面積は156m²です。',null);
  add('area','advanced','たて20m、横30mの畑に、はば１mの道を、たてに１本、横に１本、十字に作ります。道の面積は何m²ですか。',49,[50,51,600],['横の道とたての道の面積を、それぞれ求めます。','真ん中の１m²は、２回数えています。'],'横の道は30×1＝30m²、たての道は20×1＝20m²です。重なった１m²を引くと、30＋20－1＝49。道の面積は49m²です。',null);
  add('area','advanced','１辺が500mの正方形の土地は、何haですか。',25,[2.5,250,2500],['まず面積をm²で求めます。','１ha＝10000m²です。'],'500 × 500＝250000m²。250000 ÷ 10000＝25。面積は25haです。',null);
  add('area','advanced','面積が81cm²の正方形があります。この正方形のまわりの長さは何cmですか。',36,[9,18,81],['面積は、１辺×１辺です。何×何＝81でしょう。','１辺がわかったら、まわりの長さを求めます。'],'9 × 9＝81なので、１辺は９cmです。まわりの長さは 9 × 4＝36cmです。',null);
  add('area','advanced','３m²は何cm²ですか。',30000,[300,3000,300000],['１m²＝10000cm²です。','10000を３倍します。'],'１m²＝10000cm²なので、３m²＝30000cm²です。',null);
