  add('expression','basic','（8＋2）×5を計算しましょう。',50,[18,20,15],['かっこの中を先に計算します。','8＋2＝10を５倍します。'],'かっこの中を先に計算します。（8＋2）×5＝10×5＝50です。',null);
  add('expression','basic','20－12÷4を計算しましょう。',17,[2,8,5],['わり算を先に計算します。','12÷4＝3を、20から引きます。'],'12÷4＝3を先に計算します。20－3＝17です。',null);
  add('expression','basic','たし算・ひき算と、かけ算・わり算がまじった式では、どちらを先に計算しますか。','かけ算・わり算',['たし算・ひき算','左から順に、どれも同じ','右から順に'],['かっこがないときの、計算の決まりを思い出しましょう。','かけ算とわり算は、たし算とひき算より先に計算します。'],'かっこがない式では、かけ算・わり算を先に計算し、そのあとでたし算・ひき算をします。',null);
  add('expression','basic','かっこのある式では、どこを先に計算しますか。','かっこの中',['かっこの外','右はし','かけ算だけ'],['かっこは、「先にやります」という印です。','かっこの中を１つのかたまりと考えます。'],'かっこのある式では、かっこの中を先に計算します。',null);
  add('expression','basic','１さつ90円のノートを３さつ買って、500円出しました。おつりを求める式はどれですか。','500－90×3',['（500－90）×3','500＋90×3','500÷90×3'],['ノート３さつ分の代金を先に求めます。','出したお金から、代金を引きます。'],'ノート３さつ分の代金は90×3円です。おつりは、500－90×3で求められます。',null);
  add('expression','basic','12÷3×2を計算しましょう。',8,[2,6,18],['わり算とかけ算だけの式は、左から順に計算します。','12÷3を先に計算します。'],'左から順に、12÷3＝4、4×2＝8です。',null);

