  add('expression','standard','36÷（2＋4）＋5を計算しましょう。',11,[23,8,1],['かっこの中を先に計算します。','次にわり算をして、最後に5を足します。'],'2＋4＝6、36÷6＝6、6＋5＝11です。',null);
  add('expression','standard','25×12を、25×4×3と考えて計算します。答えはいくつですか。',300,[250,100,75],['25×4＝100を先に作ります。','100に3をかけます。'],'12＝4×3なので、25×12＝25×4×3＝100×3＝300です。',null);
