  add('expression','standard','99×7を、（100－1）×7と考えて計算します。答えはいくつですか。',693,[707,700,792],['99は、100より1小さい数です。','100×7から、1×7を引きます。'],'99×7＝（100－1）×7＝700－7＝693です。',null);
  add('expression','standard','１本120円のジュースを４本と、80円のパンを１こ買いました。代金はいくらですか。',560,[200,600,480],['ジュースの代金を、かけ算で求めます。','それに、パンの代金を足します。'],'120×4＋80＝480＋80＝560。代金は560円です。',null);
  add('expression','standard','１こ50円のあめを５こと、１こ30円のガムを４こ買いました。代金は全部でいくらですか。',370,[320,80,270],['あめの代金と、ガムの代金を、それぞれ求めます。','２つの代金を足します。'],'50×5＋30×4＝250＋120＝370。全部で370円です。',null);
  add('expression','standard','（□＋3）×4＝28です。□にあてはまる数はいくつですか。',4,[7,10,25],['28÷4を先に考えます。','□＋3が、いくつになるか考えます。'],'□＋3＝28÷4＝7なので、□＝7－3＝4です。',null);
  add('expression','standard','□×6－5＝31です。□にあてはまる数はいくつですか。',6,[5,4,36],['31に5を足すと、□×6になります。','36を6でわります。'],'□×6＝31＋5＝36なので、□＝36÷6＝6です。',null);
