  add('large','advanced','３億と、２億5000万の差は、いくつですか。',50000000,[500000000,5000000,5000000000],['３億は、３億0000万と書けます。','３億から２億5000万を引きます。'],'３億－２億5000万＝5000万。数字で書くと、50000000です。',null);
  add('large','advanced','１兆は、1000億の何倍ですか。',10,[100,1000,1],['１兆は、10000億です。','1000億が何こ集まった数か考えます。'],'１兆＝10000億なので、1000億の10倍です。',null);
  add('large','advanced','十億の位が７、千万の位が４で、ほかの位がすべて０の数を、数字で書きましょう。',7040000000,[704000000,7400000000,70400000000],['十億の位は、右から10番目の位です。','千万の位は、右から８番目の位です。'],'十億の位が７、千万の位が４なので、7040000000です。',null);
  add('large','advanced','Ａは３億2000万、Ｂは３億200万です。どちらがいくつ大きいですか。','Ａが1800万大きい',['Ｂが1800万大きい','Ａが1億8000万大きい','Ａが180万大きい'],['３億は同じです。','2000万と200万の差を考えます。'],'３億は同じなので、2000万－200万＝1800万。Ａが1800万大きいです。',null);

  // がい数（29問）
  add('round','basic','3452を、四捨五入して百の位までのがい数にしましょう。',3500,[3400,3000,3450],['百の位の１つ下の、十の位を見ます。','十の位は５なので、切り上げます。'],'十の位の５を四捨五入して、3500です。',null);
  add('round','basic','四捨五入で、切り上げるのは、そのすぐ下の位の数が何以上のときですか。','５以上',['４以上','６以上','０以上'],['四捨五入の「五入」にあたる場合です。','５、６、７、８、９のときです。'],'すぐ下の位の数が５以上のときは切り上げ、４以下のときは切り捨てます。',null);
  add('round','basic','78を、四捨五入して十の位までのがい数にしましょう。',80,[70,78,100],['十の位の１つ下の、一の位を見ます。','一の位は８なので、切り上げます。'],'一の位の８を四捨五入して、80です。',null);
  add('round','basic','6240を、四捨五入して千の位までのがい数にしましょう。',6000,[7000,6200,6300],['千の位の１つ下の、百の位を見ます。','百の位は２なので、切り捨てます。'],'百の位の２を四捨五入して、6000です。',null);
  add('round','basic','「がい数」とは、どんな数ですか。','およその数',['正しい数','いちばん大きい数','整数でない数'],['「がい」は「おおよそ」という意味です。','四捨五入などで、切りのよい数にします。'],'がい数とは、おおよその数のことです。',null);
  add('round','basic','4500を、四捨五入して千の位までのがい数にしましょう。',5000,[4000,4500,6000],['千の位の１つ下の、百の位を見ます。','百の位はちょうど５です。５は切り上げます。'],'百の位の５は切り上げるので、5000です。',null);
  add('round','basic','49を、四捨五入して十の位までのがい数にしましょう。',50,[40,49,60],['一の位を見ます。','一の位は９なので、切り上げます。'],'一の位の９を四捨五入して、50です。',null);

  add('round','standard','27648を、四捨五入して上から１けたのがい数にしましょう。',30000,[20000,28000,27000],['上から１けた目の、すぐ下の位を見ます。','万の位が２、その下の千の位が７です。'],'千の位の７を四捨五入して、30000です。',null);
  add('round','standard','4562を、四捨五入して上から２けたのがい数にしましょう。',4600,[4500,4560,5000],['上から２けた目は、百の位です。','その下の、十の位を見ます。'],'十の位の６を四捨五入して、4600です。',null);
  add('round','standard','雪原基地の村の人が235人、バスで出かけます。バスは１台に50人まで乗れます。何台あれば全員が乗れますか。',5,[4,6,235],['235÷50を考えます。','あまりが出たら、もう１台必要です。'],'235÷50＝４あまり35。あまった35人も乗るので、５台必要です（切り上げ）。',null);
  add('round','standard','1000円で、１こ120円のおにぎりを、できるだけ多く買います。何こ買えますか。',8,[9,10,7],['1000÷120を考えます。','買えるのは、代金が1000円をこえない数までです。'],'1000÷120＝８あまり40。９こ買うと1080円で足りないので、８こ買えます（切り捨て）。',null);
  add('round','standard','3980円と5120円を、千の位までのがい数にして足し、およその合計を求めましょう。',9000,[8000,10000,9100],['それぞれを、千の位までのがい数にします。','4000と5000を足します。'],'3980→4000、5120→5000。4000＋5000＝9000円です。',null);
  add('round','standard','598×６を、598を600と見て、見積もりましょう。およそいくつですか。',3600,[3000,3588,3500],['598は、600に近い数です。','600×６を計算します。'],'598を600とすると、600×6＝3600。およそ3600です。',null);
  add('round','standard','四捨五入して百の位までのがい数にしたとき、5000になる整数のうち、いちばん大きい数はいくつですか。',5049,[5000,5050,4999],['５０００になるはんいは、4950から5049までです。','5050は、切り上げて5100になります。'],'十の位が４までなら切り捨てて5000です。いちばん大きいのは5049です。',null);
  add('round','standard','100以上200未満の整数のうち、いちばん小さい数はいくつですか。',100,[99,101,200],['以上は、その数をふくみます。','100以上なので、100も入ります。'],'100以上は100をふくむので、いちばん小さい数は100です。',null);
  add('round','standard','次の数のうち、四捨五入して千の位までのがい数にすると4000になる数を選びましょう。','3600',['3400','4600','4500'],['千の位まで四捨五入するので、百の位を見ます。','3500以上4499以下の数が4000になります。'],'3600は、百の位の６を切り上げて4000になります。3400は3000、4500は5000です。',null);
  add('round','standard','村の人口は23547人です。四捨五入して万の位までのがい数にすると、約何人ですか。',20000,[24000,23000,30000],['万の位の１つ下の、千の位を見ます。','千の位は３なので、切り捨てます。'],'千の位の３を四捨五入して、20000人です。',null);
  add('round','standard','3470を、四捨五入して上から１けたのがい数にしましょう。',3000,[3500,3400,4000],['上から１けた目は千の位です。','その下の、百の位を見ます。'],'百の位の４を四捨五入して、3000です。',null);

  add('round','advanced','四捨五入して百の位までのがい数にすると3500になる整数のはんいは、どれですか。','3450以上3549以下',['3500以上3599以下','3400以上3499以下','3450以上3550以下'],['百の位までなので、十の位を見ます。','切り上げて3500になるのは3450から、切り捨てて3500になるのは3549までです。'],'3450から3549までの整数が、百の位までのがい数にすると3500になります。',null);
  add('round','advanced','四捨五入して十の位までのがい数にすると60になる整数は、全部で何こありますか。',10,[9,11,5],['55から64までを数えます。','55、56、…、64です。'],'55以上64以下の整数なので、64－55＋1＝10こです。',null);
  add('round','advanced','498円、302円、1198円の品物を買います。それぞれ百の位までのがい数にして、およその代金を求めましょう。',2000,[1900,2100,1998],['それぞれ500円、300円、1200円になります。','それらを足します。'],'500＋300＋1200＝2000。およそ2000円です。',null);
  add('round','advanced','全員で183人います。１台に40人まで乗れるバスで出かけるとき、バスは何台必要ですか。',5,[4,6,3],['183÷40を計算します。','あまりの人も乗るので、もう１台必要です。'],'183÷40＝４あまり23。あまった23人も乗るので、５台必要です。',null);
  add('round','advanced','１つのテントに５人まで入れます。47人がテントに入るには、テントは何はり必要ですか。',10,[9,11,8],['47÷5を計算します。','あまりの２人のために、もう１はり必要です。'],'47÷5＝９あまり２。あまりの２人のためにもう１はり必要で、10はりです。',null);
  add('round','advanced','1000円を持っています。298円、385円、217円の品物を買います。それぞれ百の位までのがい数にして見積もると、代金が1000円で足りるかどうか、次のうちどれですか。','足りる',['足りない','ちょうどになる','見積もれない'],['それぞれ300円、400円、200円になります。','合計を、1000円と比べます。'],'300＋400＋200＝900円で、1000円より少ないので足ります（本当は900円）。',null);
  add('round','advanced','四捨五入して千の位までのがい数にすると12000になる整数のはんいは、どれですか。','11500以上12499以下',['12000以上12999以下','11000以上11999以下','11500以上12500以下'],['百の位を見て四捨五入します。','切り上げて12000になるのは11500から、切り捨てて12000になるのは12499までです。'],'11500以上12499以下の整数が、千の位までのがい数にすると12000になります。',null);
  add('round','advanced','３けたの整数で、四捨五入して百の位までのがい数にすると400になる、いちばん小さい数はいくつですか。',350,[300,349,399],['350から399までは、切り上げて400です。','349は切り捨てて300です。'],'十の位が５以上の350から、切り上げて400になります。350が最小です。',null);
  add('round','advanced','四捨五入して十の位までのがい数にすると350になる整数のうち、いちばん大きい数はいくつですか。',354,[349,355,359],['一の位を見て四捨五入します。','切り捨てて350になるのは、一の位が４までです。'],'350から354までは切り捨てて350になります。355は切り上げて360です。いちばん大きいのは354です。',null);
  add('round','advanced','4180×39を、それぞれ上から１けたのがい数にして見積もりましょう。およそいくつですか。',160000,[120000,156000,200000],['4180は4000、39は40になります。','4000×40を計算します。'],'4180→4000、39→40。4000×40＝160000です。',null);
  add('round','advanced','2500mlの水を、1000mlの入れ物に入れていきます。入れ物は何こ必要ですか。',3,[2,4,25],['2500÷1000を計算します。','あまった水も入れ物に入れます。'],'2500÷1000＝２あまり500。あまりの水のためにもう１こ必要で、３こです。',null);
